<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Notification Preferences</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f3f6fb;
      --surface: #ffffff;
      --surface-muted: #f8fafc;
      --text: #172033;
      --text-muted: #52607a;
      --border: #d5deeb;
      --accent: #3b82f6;
      --accent-strong: #1d4ed8;
      --shadow: 0 24px 60px rgba(15, 23, 42, 0.14);
      --radius: 20px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top left, #dbeafe 0, transparent 28%),
        linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
      color: var(--text);
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: -3rem;
      padding: 0.75rem 1rem;
      background: var(--surface);
      color: var(--text);
      border-radius: 0.75rem;
      box-shadow: var(--shadow);
      z-index: 10;
    }

    .skip-link:focus {
      top: 1rem;
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 2rem 1rem;
    }

    .card {
      width: min(100%, 640px);
      background: var(--surface);
      border: 1px solid rgba(213, 222, 235, 0.9);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: clamp(1.5rem, 3vw, 2.5rem);
    }

    .eyebrow {
      margin: 0 0 0.5rem;
      color: var(--accent-strong);
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      font-size: 0.8rem;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.8rem, 5vw, 2.6rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0.85rem 0 0;
      color: var(--text-muted);
      font-size: 1rem;
      line-height: 1.6;
    }

    form {
      margin-top: 2rem;
    }

    .form-field {
      margin: 0;
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      margin-bottom: 1rem;
      padding: 0;
      font-size: 1.05rem;
      font-weight: 700;
    }

    .choices {
      display: grid;
      gap: 0.85rem;
    }

    .choice {
      display: flex;
      align-items: center;
      gap: 0.9rem;
      padding: 1rem 1.1rem;
      background: var(--surface-muted);
      border: 1px solid var(--border);
      border-radius: 1rem;
      cursor: pointer;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    .choice:hover {
      border-color: #a7c4ff;
      transform: translateY(-1px);
    }

    .choice input {
      width: 1.15rem;
      height: 1.15rem;
      margin: 0;
      accent-color: var(--accent-strong);
      flex-shrink: 0;
    }

    .choice-content {
      display: flex;
      flex-direction: column;
      gap: 0.2rem;
    }

    .choice-title {
      font-weight: 600;
    }

    .choice-copy {
      color: var(--text-muted);
      font-size: 0.95rem;
    }

    .choice:has(input:checked) {
      border-color: var(--accent);
      box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.14);
      background: #eff6ff;
    }

    .choice:has(input:focus-visible) {
      outline: 3px solid rgba(29, 78, 216, 0.35);
      outline-offset: 2px;
    }

    .actions {
      margin-top: 1.5rem;
      display: flex;
      align-items: center;
      gap: 1rem;
      flex-wrap: wrap;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.4rem;
      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
      color: #ffffff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease;
      box-shadow: 0 14px 28px rgba(29, 78, 216, 0.22);
    }

    button:hover {
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid rgba(29, 78, 216, 0.35);
      outline-offset: 3px;
    }

    .status {
      min-height: 1.5rem;
      color: var(--text-muted);
      font-weight: 600;
    }

    @media (max-width: 480px) {
      .card {
        padding: 1.25rem;
      }
    }

    @media (forced-colors: active) {
      .card,
      .choice,
      button {
        border: 1px solid ButtonText;
        box-shadow: none;
      }

      .card,
      .choice {
        background: Canvas;
        color: CanvasText;
      }

      button {
        background: ButtonFace;
        color: ButtonText;
      }

      .choice:has(input:checked),
      .choice:hover {
        background: Highlight;
        color: HighlightText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content">
    <section class="card" aria-labelledby="page-title">
      <p class="eyebrow">Preferences</p>
      <h1 id="page-title">Choose your notification style</h1>
      <p class="intro">Tell us how you prefer to hear from us so we can keep updates relevant and easy to manage.</p>

      <form id="notification-form">
        <div class="form-field">
          <fieldset>
            <legend>How do you prefer to receive notifications?</legend>
            <div class="choices">
              <label class="choice" for="notify-email">
                <input id="notify-email" type="radio" name="notificationPreference" value="Email" required>
                <span class="choice-content">
                  <span class="choice-title">Email</span>
                  <span class="choice-copy">Best for detailed updates and summaries.</span>
                </span>
              </label>

              <label class="choice" for="notify-sms">
                <input id="notify-sms" type="radio" name="notificationPreference" value="SMS">
                <span class="choice-content">
                  <span class="choice-title">SMS</span>
                  <span class="choice-copy">Quick alerts delivered straight to your phone.</span>
                </span>
              </label>

              <label class="choice" for="notify-push">
                <input id="notify-push" type="radio" name="notificationPreference" value="Push Notifications">
                <span class="choice-content">
                  <span class="choice-title">Push Notifications</span>
                  <span class="choice-copy">Instant app updates when something important happens.</span>
                </span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Submit</button>
          <p id="form-status" class="status" aria-live="polite"></p>
        </div>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById("notification-form");
    const status = document.getElementById("form-status");

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const selected = form.querySelector('input[name="notificationPreference"]:checked');
      status.textContent = selected
        ? `Preference saved: ${selected.value}.`
        : "Please choose a notification preference.";
    });
  </script>
</body>
</html>
